import { questions, categories, sources, VERIFIED_AT, QUESTION_VERSION } from './data.js';
import { score } from './state.js';
import { mapSVG, stationList, lineLegend } from './map.js';
export const arrow = '<span aria-hidden="true">→</span>';
export function homeScreen(model) {
  const resumable = model.attempt && !model.attempt.completed;
  return `<section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="eyebrow-dot"></span>Перевір себе</div><h1 tabindex="-1">Наскільки добре<br>ти знаєш метро<br><span>Харкова?</span></h1><p class="hero-description">12 запитань про станції, <br>пересадки та історію</p>
    <div class="start-actions"><button class="button primary" data-action="${resumable?'resume':'start'}">${resumable?'Продовжити тест':'Почати тест'} ${arrow}</button>${resumable?'<button class="text-button" data-action="start">Почати заново</button>':''}</div>
    <p class="small-note">Одна правильна відповідь у кожному запитанні</p>
    ${resumable?`<p class="resume-note">Збережено ${Object.keys(model.attempt.answers).length} із 12 відповідей</p>`:''}
    ${model.best !== null ? `<p class="resume-note">Найкращий результат: <strong>${model.best} із 12</strong>${model.attempt?.completed ? ' · <a href="#result">Останній результат ↗</a>' : ''}</p>` : ''}
    ${model.notice?`<p class="storage-notice" role="status">${model.notice}</p>`:''}${lineLegend()}</div>
    <div class="map-panel"><div class="map-panel-head"><span>Схема метрополітену</span><button class="text-button" data-action="map">Збільшити <span aria-hidden="true">↗</span></button></div>${mapSVG()}<div class="map-panel-foot"><span class="small-note">Актуальні назви станцій</span><button class="text-button" data-action="animate">▷ Відтворити анімацію</button></div></div></section>${stationList()}
    <section class="reference-section"><div><span class="section-number">01 / Референс</span><h2>Вихідна схема</h2><p>З цієї карти почався проєкт.</p><p class="small-note">Зображення містить попередні назви станцій і користувацькі помітки. Використовуємо його як візуальний референс.</p><button class="button secondary" data-action="original">Переглянути оригінал <span aria-hidden="true">↗</span></button></div><figure class="reference-image"><img src="./assets/original-map.png" width="766" height="699" loading="lazy" alt="Вихідна схема Харківського метро зі старими назвами станцій і червоними користувацькими помітками"><figcaption>Надане зображення · не актуальна довідкова схема</figcaption></figure></section>`;
}
export function quizScreen(model) {
  const a = model.attempt, q = questions[a.currentIndex], count = Object.keys(a.answers).length;
  return `<section class="quiz-shell"><a class="back-link" href="#home">← На головну</a><div class="quiz-top"><span>Запитання ${a.currentIndex+1} із 12</span><span class="answered-count">Відповіді: ${count} із 12</span></div>
    <div class="route-progress" role="img" aria-label="Запитання ${a.currentIndex+1} із 12; відповіді: ${count} із 12"><div class="progress-track"></div>${questions.map((q,i)=>`<span class="progress-stop ${a.answers[q.id]?'answered':''} ${i===a.currentIndex?'current':''}" aria-hidden="true">${i===a.currentIndex?'<span></span>':''}</span>`).join('')}</div>
    <div class="question-card"><fieldset><legend tabindex="-1" id="question-title">${q.text}</legend><div class="answers">${a.order[q.id].map((id,i)=>{const o=q.options.find(o=>o.id===id);return `<label class="answer-card ${a.answers[q.id]===id?'selected':''}"><input type="radio" name="answer-${q.id}" value="${o.id}" ${a.answers[q.id]===id?'checked':''}><span class="answer-letter" aria-hidden="true">${['А','Б','В','Г'][i]}</span><span class="answer-text">${o.text}</span><span class="radio-visual" aria-hidden="true"></span></label>`}).join('')}</div></fieldset>
    <div class="quiz-navigation"><div>${a.currentIndex>0?'<button class="button secondary" data-action="back">← Назад</button>':''}</div><div class="next-group"><span class="selection-hint small-note" ${a.answers[q.id]?'hidden':''}>Оберіть одну відповідь</span><button class="button primary" data-action="next" ${a.answers[q.id]?'':'disabled'}>${a.currentIndex===11?'Завершити тест':'Далі'} ${arrow}</button></div></div></div>
    <p class="quiz-note small-note"><span aria-hidden="true">◌</span> Можна повернутися назад і змінити відповідь</p>
    ${!model.available?'<p class="storage-notice" role="status">Прогрес зберігається лише в пам’яті цієї сторінки.</p>':''}</section>`;
}
export function resultScreen(model) {
  const r = score(model.attempt);
  return `<section class="result-shell"><div class="eyebrow"><span class="eyebrow-dot"></span>Маршрут завершено</div><h1 tabindex="-1" class="screen-title">Твій результат</h1><div class="result-score"><span>${r.correct}</span><span class="score-denominator">із 12</span></div><h2 class="result-level">${r.level}</h2><div class="score-bar" role="img" aria-label="${r.percent} відсотків правильних відповідей"><span style="width:${r.percent}%"></span></div><div class="result-meta"><span>${r.percent}% правильних відповідей</span><span>Найкраще: ${model.best} із 12</span></div>
    <div class="category-results"><h3>Як пройдено кожну лінію</h3>${r.categories.map(c=>`<div class="category-row"><div><span><i class="category-dot ${c.color}" aria-hidden="true"></i>${c.label}</span><strong>${c.correct} із ${c.total}</strong></div><div class="category-bar" aria-hidden="true"><span class="${c.color}" style="width:${c.correct/c.total*100}%"></span></div></div>`).join('')}</div>
    <div class="result-actions"><a class="button primary" href="#review">Переглянути відповіді ${arrow}</a><button class="button secondary" data-action="start">Пройти ще раз</button><a class="text-button" href="#home">На головну</a></div><p class="small-note editorial-note">Це редакційна шкала тесту, а не офіційна оцінка знань.</p></section>`;
}
export function reviewScreen(model, errorsOnly = false) {
  const wrong = questions.filter(q => model.attempt.answers[q.id] !== q.correctOptionId);
  const shown = errorsOnly ? wrong : questions;
  return `<section class="review-shell"><a href="#result" class="back-link">← До результату</a><div class="review-header"><div><div class="eyebrow">Після маршруту</div><h1 tabindex="-1" class="screen-title">Розбір відповідей</h1></div><div class="filter-tabs" role="group" aria-label="Фільтр запитань"><button data-action="filter-all" aria-pressed="${!errorsOnly}">Усі запитання <span>12</span></button><button data-action="filter-errors" aria-pressed="${errorsOnly}">Лише помилки <span>${wrong.length}</span></button></div></div>
    ${shown.length ? shown.map(q=>{const chosen=q.options.find(o=>o.id===model.attempt.answers[q.id]);const right=q.options.find(o=>o.id===q.correctOptionId);const correct=chosen.id===right.id;return `<article class="review-card"><div class="review-card-meta"><span>Запитання ${questions.indexOf(q)+1} · ${categories.find(c=>c.id===q.category).label}</span><span class="status ${correct?'correct':'incorrect'}">${correct?'✓ Правильно':'✕ Помилка'}</span></div><h2>${q.text}</h2>${!correct?`<div class="review-answer wrong"><span>Твій вибір · ✕ Неправильно</span><strong>${chosen.text}</strong></div>`:''}<div class="review-answer right"><span>${correct?'Твій вибір · ✓ Правильно':'Правильна відповідь · ✓'}</span><strong>${right.text}</strong></div><p class="explanation">${q.explanation}</p><div class="source-links">${q.sources.map(s=>`<a href="${s.url}" target="_blank" rel="noopener noreferrer">Джерело: ${s.title} ↗</a>`).join('')}</div></article>`}).join('') : '<div class="empty-state"><span aria-hidden="true">✓</span><h2>Жодної помилки</h2><p>Усі 12 відповідей правильні. Можна переглянути всі запитання та пояснення.</p><button class="button secondary" data-action="filter-all">Показати всі запитання</button></div>'}
    <div class="result-actions"><a class="button secondary" href="#result">До результату</a><button class="button primary" data-action="start">Пройти ще раз ${arrow}</button></div></section>`;
}
export function aboutScreen(model) {
  return `<section class="about-shell"><a class="back-link" href="${model.attempt&&!model.attempt.completed?'#quiz':'#home'}">← ${model.attempt&&!model.attempt.completed?'Повернутися до тесту':'На головну'}</a><div class="eyebrow">Дані, яким можна довіряти</div><h1 tabindex="-1" class="screen-title">Про тест і джерела</h1><p class="about-lead">12 запитань, щоб перевірити знання станцій, пересадок та історії Харківського метро.</p><div class="about-block"><h2>Як працює тест</h2><p>У кожному запитанні чотири варіанти та одна правильна відповідь. Можна змінювати вибір і повертатися до попередніх запитань. Пояснення відкриваються після завершення.</p><ul class="about-categories">${categories.map(c=>`<li><span class="category-dot ${c.color}" aria-hidden="true"></span>${c.label}<span>${c.total} ${c.total === 6 ? 'запитань' : 'запитання'}</span></li>`).join('')}</ul><p>Правильна відповідь — один бал. Результат від 0 до 12; відсоток округлюється до цілого. Рівні 0–4, 5–8 і 9–12 — внутрішня редакційна шкала цього тесту.</p></div><div class="about-block"><h2>Офіційні джерела</h2><p class="small-note">Інформацію перевірено 04.10.2026 · Версія запитань ${QUESTION_VERSION}</p><ul class="official-sources">${Object.values(sources).map((s,i)=>`<li><span class="source-index">${String(i+1).padStart(2,'0')}</span><a href="${s.url}" target="_blank" rel="noopener noreferrer">${s.title}<span aria-hidden="true">↗</span></a></li>`).join('')}</ul></div><div class="about-block"><h2>Схема та приватність</h2><p>Назви й порядок станцій у чистій схемі звірено з офіційними сторінками трьох ліній. Схема умовна й не відображає географічних відстаней. Початкове зображення зі старими назвами та помітками доступне на головній.</p><p>Прогрес і найкращий результат зберігаються лише в цьому браузері. Персональні дані не збираються, відповіді не надсилаються на сервер. Декоративний маркер на схемі не показує рух реальних поїздів.</p><p class="small-note">Шрифт <a class="inline-link" href="https://thedigital.gov.ua/fonts" target="_blank" rel="noopener noreferrer">e-Ukraine — Міністерство цифрової трансформації України ↗</a>. Локальні файли Regular і Bold. Матеріали міністерства — CC BY 4.0. Кольори схеми — дизайнерський підбір за референсом.</p></div></section>`;
}

